  let r2 = dot(in.quad_uv, in.quad_uv);
  if (r2 > 1.0) {
    discard;
  }
  let edge = 1.0 - smoothstep(0.72, 1.0, r2);
  return vec4<f32>(in.color.rgb * in.color.a * edge, in.color.a * edge);
